// Package operations exposes the Gate API operation catalog (REQ-006 BR-3 / BR-10).
//
// The catalog is generated by tools/catalog/gen_interface_json.py from gateapiv4 OpenAPI
// specs and embedded into the binary at build time. Lookup is used by the
// unauthenticated client guard to decide whether an outbound request hits a public
// or private endpoint without requiring per-command annotations.
package operations

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"sync"
)

//go:embed interface.json
var rawCatalog []byte

// Operation is the minimal metadata REQ-006 BR-10 needs to enforce the access
// matrix. Additional fields can be added later without breaking callers since
// this struct is consumed only inside this module.
type Operation struct {
	Method       string `json:"method"`
	Path         string `json:"path"`
	OperationID  string `json:"operation_id"`
	Module       string `json:"module"`
	AuthRequired bool   `json:"auth_required"`
}

type catalog struct {
	Version    string      `json:"version"`
	Operations []Operation `json:"operations"`
}

// templateEntry holds a path template (e.g. /api/v4/spot/currencies/{currency})
// compiled into a regex so it can be matched against concrete URLs at runtime.
type templateEntry struct {
	op *Operation
	re *regexp.Regexp
}

var (
	loadOnce sync.Once
	loadErr  error
	exactIdx map[string]*Operation      // key: METHOD + " " + path (no {var})
	tmplIdx  map[string][]templateEntry // key: METHOD; templates only
)

func ensureLoaded() error {
	loadOnce.Do(func() {
		var c catalog
		if err := json.Unmarshal(rawCatalog, &c); err != nil {
			loadErr = fmt.Errorf("operations: parse interface.json: %w", err)
			return
		}
		exactIdx = make(map[string]*Operation, len(c.Operations))
		tmplIdx = make(map[string][]templateEntry)
		for i := range c.Operations {
			op := &c.Operations[i]
			if strings.Contains(op.Path, "{") {
				re, err := compileTemplate(op.Path)
				if err != nil {
					loadErr = fmt.Errorf("operations: compile template %q: %w", op.Path, err)
					return
				}
				tmplIdx[op.Method] = append(tmplIdx[op.Method], templateEntry{op: op, re: re})
				continue
			}
			exactIdx[op.Method+" "+op.Path] = op
		}
	})
	return loadErr
}

var tmplVarRe = regexp.MustCompile(`\{[^/{}]+\}`)

func compileTemplate(p string) (*regexp.Regexp, error) {
	parts := tmplVarRe.Split(p, -1)
	for i, seg := range parts {
		parts[i] = regexp.QuoteMeta(seg)
	}
	pattern := "^" + strings.Join(parts, `[^/]+`) + "$"
	return regexp.Compile(pattern)
}

// Lookup returns the Operation matching method+path, or nil if no entry exists.
// Path must be the URL path only (no query string, no host).
func Lookup(method, path string) (*Operation, error) {
	if err := ensureLoaded(); err != nil {
		return nil, err
	}
	if op, ok := exactIdx[method+" "+path]; ok {
		return op, nil
	}
	for _, entry := range tmplIdx[method] {
		if entry.re.MatchString(path) {
			return entry.op, nil
		}
	}
	return nil, nil
}

// LookupByID reads the same catalog used for route governance. Returning a value
// protects shared metadata from diagnostic callers; ambiguous IDs are errors.
func LookupByID(id string) (Operation, error) {
	if err := ensureLoaded(); err != nil {
		return Operation{}, err
	}
	return lookupOperationID(id, exactIdx, tmplIdx)
}

func lookupOperationID(id string, exact map[string]*Operation, templates map[string][]templateEntry) (Operation, error) {
	var found *Operation
	accept := func(op *Operation) error {
		if op.OperationID != id {
			return nil
		}
		if found != nil {
			return fmt.Errorf("operations: ambiguous operation ID %q", id)
		}
		found = op
		return nil
	}
	for _, op := range exact {
		if err := accept(op); err != nil {
			return Operation{}, err
		}
	}
	for _, entries := range templates {
		for _, entry := range entries {
			if err := accept(entry.op); err != nil {
				return Operation{}, err
			}
		}
	}
	if found == nil {
		return Operation{}, fmt.Errorf("operations: unknown operation ID %q", id)
	}
	return *found, nil
}

// IsPublic reports whether the given method+path is a known public endpoint
// (auth_required=false). Unknown endpoints return false: fail-closed, prefer
// prompting the user to authenticate over silently sending an anonymous
// request to a private API.
func IsPublic(method, path string) bool {
	op, err := Lookup(method, path)
	if err != nil || op == nil {
		return false
	}
	return !op.AuthRequired
}

// Count returns total / public counts; useful for diagnostics and tests.
func Count() (total, public int, err error) {
	if err := ensureLoaded(); err != nil {
		return 0, 0, err
	}
	for _, op := range exactIdx {
		total++
		if !op.AuthRequired {
			public++
		}
	}
	for _, entries := range tmplIdx {
		for _, e := range entries {
			total++
			if !e.op.AuthRequired {
				public++
			}
		}
	}
	return total, public, nil
}
